// FIBO Node Atlas: a browser for the classified FIBO graph in data.js.
//
// data.js (generated by fibo_classify.py) defines window.FIBO_DATA with:
//   meta   - corpus totals, tier descriptions, field order of each node record
//   pools  - interned string tables (namespaces, files, tiers, domains, ...)
//   nodes  - one compact array per node; meta.fields names each position
//   edges  - [subject, object, predicate] index triples (type/subClassOf omitted)

(() => {
  "use strict";

  const DATA = window.FIBO_DATA;
  const FIELD = Object.fromEntries(
    DATA.meta.fields.map((name, i) => [name, i]),
  );
  const POOL = DATA.pools;
  const NODES = DATA.nodes;

  const TIER_ORDER = [
    "concept",
    "property",
    "individual",
    "external-vocab",
    "external-ref",
    "structure",
    "machinery",
  ];

  const TIER_HELP = {
    concept:
      "The vocabulary itself: what a lender, a buyer, a loan or a payment obligation is. Start here. Each class has a definition, superclasses and the constraints that describe it.",
    property:
      "The verbs and attributes that connect concepts: who is a party to a contract, what currency an amount is in, when something matured.",
    individual:
      "Catalogued instances rather than concepts: specific exchanges and their market identifier codes, currencies, countries, interest rate benchmarks, legal entities. Useful as lookup data, not as vocabulary.",
    "external-vocab":
      "Terms FIBO reuses from ontologies it imports but which are not in this folder (OMG Commons, ISO country codes, W3C). They appear as superclasses and property ranges without their own definitions here.",
    "external-ref":
      "Web pages, GLEIF records and other documents cited as sources. They are nodes only because something points at them. Supportive context, not concepts.",
    structure:
      "Packaging: one owl:Ontology per file, module groupings, version IRIs. Tells you where things live, not what they mean.",
    machinery:
      'Anonymous OWL nodes such as "hasLender some Lender". They carry the formal constraints on classes; the browser folds them into each class as readable constraint lines.',
  };

  // Tiers whose overview card breaks down by source domain rather than concept family.
  const TIERS_BY_DOMAIN = new Set(["external-ref", "external-vocab"]);

  const FIBO_IRI_PREFIX = "https://spec.edmcouncil.org/";
  const PAGE_SIZE = 200;
  const PAGE_STEP = 500;
  const OVERVIEW_BARS = 8;
  const LIST_LIMIT = 40;
  const RELATION_LIMIT = 60;

  // ---------------------------------------------------------------- accessors

  const field = (nodeId, name) => NODES[nodeId][FIELD[name]];
  const nameOf = (nodeId) => field(nodeId, "name");
  const iriOf = (nodeId) => POOL.ns[field(nodeId, "ns")] + nameOf(nodeId);
  const labelOf = (nodeId) =>
    field(nodeId, "label") || nameOf(nodeId) || "(blank node)";
  const tierOf = (nodeId) => POOL.tier[field(nodeId, "tier")];
  const domainOf = (nodeId) => POOL.domain[field(nodeId, "domain")];
  const familyOf = (nodeId) => POOL.family[field(nodeId, "family")];
  const kindOf = (nodeId) => POOL.kind[field(nodeId, "kind")];
  const fileOf = (nodeId) => POOL.file[field(nodeId, "file")];
  const definitionOf = (nodeId) => field(nodeId, "def");
  const typeNamesOf = (nodeId) =>
    field(nodeId, "types").map((t) => POOL.type[t]);
  const superclassesOf = (nodeId) => field(nodeId, "supers");
  const constraintsOf = (nodeId) => field(nodeId, "restr");
  // The CURIE (prefix:LocalName) FIBO itself uses as a term's shortcode, from
  // the @prefix declarations in the Turtle files; "" when no prefix applies.
  const curieOf = (nodeId) => {
    const prefix = DATA.prefixes[field(nodeId, "ns")];
    return prefix && nameOf(nodeId) ? `${prefix}:${nameOf(nodeId)}` : "";
  };
  const tierName = (tierKey) => DATA.meta.tiers[tierKey] || tierKey;
  const tierColor = (tierKey) => `var(--tier-${tierKey})`;

  // Durable reference for links. FIBO terms use their IRI path below the
  // ontology base (BE/LegalEntities/CorporateBodies/ExternalAuditor); other
  // named nodes use the full IRI. Blank nodes have no identity in RDF, so they
  // fall back to a positional id that is only stable for one build of data.js.
  const FIBO_ONTOLOGY_BASE = `${FIBO_IRI_PREFIX}fibo/ontology/`;
  function slugOf(nodeId) {
    if (!nameOf(nodeId)) return `_b${nodeId}`;
    const iri = iriOf(nodeId);
    return iri.startsWith(FIBO_ONTOLOGY_BASE)
      ? iri.slice(FIBO_ONTOLOGY_BASE.length)
      : iri;
  }

  // ---------------------------------------------------------------- indexes

  function buildIndexes() {
    const subclasses = NODES.map(() => []);
    const outgoing = NODES.map(() => []);
    const incoming = NODES.map(() => []);
    const classByName = new Map();
    const instancesOf = new Map();

    NODES.forEach((_, nodeId) => {
      superclassesOf(nodeId).forEach((superId) =>
        subclasses[superId].push(nodeId),
      );
      const tier = tierOf(nodeId);
      if (
        (tier === "concept" || tier === "external-vocab") &&
        !classByName.has(nameOf(nodeId))
      ) {
        classByName.set(nameOf(nodeId), nodeId);
      }
    });

    NODES.forEach((_, nodeId) => {
      if (tierOf(nodeId) !== "individual") return;
      for (const typeName of typeNamesOf(nodeId)) {
        const classId = classByName.get(typeName);
        if (classId === undefined) continue;
        if (!instancesOf.has(classId)) instancesOf.set(classId, []);
        instancesOf.get(classId).push(nodeId);
      }
    });

    for (const [subject, object, predicate] of DATA.edges) {
      outgoing[subject].push({
        predicate: POOL.pred[predicate],
        target: object,
      });
      incoming[object].push({
        predicate: POOL.pred[predicate],
        target: subject,
      });
    }

    return { subclasses, outgoing, incoming, classByName, instancesOf };
  }

  const INDEX = buildIndexes();
  INDEX.nodeBySlug = new Map(
    NODES.map((_, nodeId) => [slugOf(nodeId), nodeId]),
  );

  const descendantCountCache = new Map();
  function descendantCount(nodeId, seen = new Set()) {
    if (descendantCountCache.has(nodeId))
      return descendantCountCache.get(nodeId);
    let count = 0;
    for (const childId of INDEX.subclasses[nodeId]) {
      if (seen.has(childId)) continue;
      seen.add(childId);
      count += 1 + descendantCount(childId, seen);
    }
    descendantCountCache.set(nodeId, count);
    return count;
  }

  // ---------------------------------------------------------------- helpers

  const formatNumber = (n) => n.toLocaleString("en-US");
  const escapeHtml = (value) =>
    String(value).replace(
      /[&<>"]/g,
      (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c],
    );
  const sortByLabel = (nodeIds) =>
    nodeIds.sort((a, b) => labelOf(a).localeCompare(labelOf(b)));
  const byId = (id) => document.getElementById(id);

  function countBy({ keyOf, filter = () => true }) {
    const counts = new Map();
    NODES.forEach((_, nodeId) => {
      if (!filter(nodeId)) return;
      const key = keyOf(nodeId);
      if (key) counts.set(key, (counts.get(key) || 0) + 1);
    });
    return counts;
  }

  function sortedEntries(counts) {
    return [...counts.entries()].sort((a, b) => b[1] - a[1]);
  }

  // ---------------------------------------------------------------- state & history
  //
  // Everything that decides what the page shows lives in `state` and is
  // mirrored into the URL hash (#browse?tier=concept&node=42). Each user
  // navigation pushes a history entry, so the browser's back button and
  // reload both work, and a hash can be shared as a link.

  const state = {
    view: "overview",
    tier: null,
    family: null,
    domain: null,
    query: "",
    selected: null,
    shown: PAGE_SIZE,
    results: [],
  };

  const VIEW_PANES = {
    overview: ["overview"],
    browse: ["filters", "results", "detail"],
    hierarchy: ["hierarchy"],
  };

  const FILTER_KEYS = ["tier", "family", "domain", "query"];

  // Search scope: "narrow" matches names only; "broad" also matches labels and
  // definitions. It is a per-browser-session preference, not part of the URL.
  const SCOPE_KEY = "fibo-atlas-search-scope";
  const SCOPES = ["narrow", "broad"];
  let searchScope = "narrow";

  function loadSearchScope() {
    try {
      const saved = sessionStorage.getItem(SCOPE_KEY);
      if (SCOPES.includes(saved)) searchScope = saved;
    } catch {
      /* storage unavailable; keep the default */
    }
  }

  function setSearchScope(scope) {
    searchScope = scope;
    try {
      sessionStorage.setItem(SCOPE_KEY, scope);
    } catch {
      /* storage unavailable; the choice lasts for this page load */
    }
    renderSearchScope();
    if (state.view === "browse") {
      applyState({ shown: PAGE_SIZE });
      renderFilters();
      renderResults();
    }
  }

  function renderSearchScope() {
    for (const button of document.querySelectorAll(".scope button")) {
      button.classList.toggle("active", button.dataset.scope === searchScope);
    }
    byId("search").placeholder =
      searchScope === "narrow"
        ? "Search names"
        : "Search names, labels, definitions";
  }

  function matchesQuery(nodeId, q) {
    if (nameOf(nodeId).toLowerCase().includes(q)) return true;
    if (searchScope === "narrow") return false;
    return (
      field(nodeId, "label").toLowerCase().includes(q) ||
      definitionOf(nodeId).toLowerCase().includes(q)
    );
  }

  const HASH_PARAMS = [
    ["tier", "tier"],
    ["family", "family"],
    ["domain", "domain"],
    ["query", "q"],
    ["selected", "node"],
  ];

  function serializeState() {
    const params = new URLSearchParams();
    for (const [key, param] of HASH_PARAMS) {
      let value = state[key];
      if (key === "selected" && value !== null) value = slugOf(value);
      if (value !== null && value !== "") params.set(param, String(value));
    }
    const query = params.toString();
    return `#${state.view}${query ? `?${query}` : ""}`;
  }

  function parseHash(hash) {
    const [view, query = ""] = hash.replace(/^#/, "").split("?");
    const params = new URLSearchParams(query);
    const parsed = { view: view in VIEW_PANES ? view : "overview" };
    for (const [key, param] of HASH_PARAMS) {
      parsed[key] = params.has(param)
        ? params.get(param)
        : key === "query"
          ? ""
          : null;
    }
    if (parsed.selected !== null) {
      parsed.selected = INDEX.nodeBySlug.get(parsed.selected) ?? null;
    }
    return parsed;
  }

  function applyState(changes) {
    const filtersChanged = FILTER_KEYS.some(
      (key) => key in changes && changes[key] !== state[key],
    );
    Object.assign(state, changes);
    if (filtersChanged) state.shown = PAGE_SIZE;
  }

  // Entry point for every user-initiated navigation.
  function navigate(changes, { replace = false } = {}) {
    applyState(changes);
    render();
    const hash = serializeState();
    if (hash === location.hash) return;
    const depth = (history.state?.depth ?? 0) + (replace ? 0 : 1);
    history[replace ? "replaceState" : "pushState"](
      { depth },
      "",
      `${location.pathname}${location.search}${hash}`,
    );
  }

  function onPopState() {
    applyState(parseHash(location.hash));
    render();
  }

  function browseTo({
    tier = null,
    family = null,
    domain = null,
    query = "",
    selected = null,
  }) {
    navigate({ view: "browse", tier, family, domain, query, selected });
  }

  function selectNode(nodeId) {
    navigate({ view: "browse", selected: nodeId });
  }

  function render() {
    const visible = new Set(VIEW_PANES[state.view]);
    for (const paneId of Object.values(VIEW_PANES).flat()) {
      byId(paneId).hidden = !visible.has(paneId);
    }
    for (const button of document.querySelectorAll(".views button")) {
      button.classList.toggle("active", button.dataset.view === state.view);
    }
    if (state.view === "browse") {
      const search = byId("search");
      if (search.value.trim().toLowerCase() !== state.query)
        search.value = state.query;
      renderFilters();
      renderPills();
      renderResults();
      renderDetailPane();
    }
    if (state.view === "hierarchy") renderHierarchy();
    renderCrumbs();
  }

  // ---------------------------------------------------------------- breadcrumbs

  const VIEW_LABELS = { browse: "Browse", hierarchy: "Class hierarchy" };

  // Each crumb navigates to the state the trail had at that point.
  function crumbTrail() {
    const trail = [
      {
        label: "Overview",
        target: {
          view: "overview",
          tier: null,
          family: null,
          domain: null,
          query: "",
          selected: null,
        },
      },
    ];
    if (state.view === "overview") return trail;
    const base = {
      view: state.view,
      tier: null,
      family: null,
      domain: null,
      query: "",
      selected: null,
    };
    trail.push({ label: VIEW_LABELS[state.view], target: { ...base } });
    if (state.view !== "browse") return trail;
    const steps = [
      ["tier", tierName],
      ["family", (v) => v],
      ["domain", (v) => v],
      ["query", (v) => `“${v}”`],
    ];
    const acc = { ...base };
    for (const [key, labelOf] of steps) {
      if (!state[key]) continue;
      acc[key] = state[key];
      trail.push({ label: labelOf(state[key]), target: { ...acc } });
    }
    if (state.selected !== null) {
      trail.push({
        label: labelOf(state.selected),
        target: { ...acc, selected: state.selected },
      });
    }
    return trail;
  }

  function renderCrumbs() {
    const nav = byId("crumbs");
    const trail = crumbTrail();
    const canGoBack = (history.state?.depth ?? 0) > 0;
    nav.hidden = trail.length === 1 && !canGoBack;
    const crumbs = trail.map((crumb, i) => {
      const last = i === trail.length - 1;
      const text = escapeHtml(crumb.label);
      return last
        ? `<span class="crumb current" aria-current="page">${text}</span>`
        : `<button type="button" class="crumb" data-crumb="${i}">${text}</button>`;
    });
    nav.innerHTML =
      (canGoBack
        ? `<button type="button" class="crumb back" data-back>← Back</button>`
        : "") + crumbs.join(`<span class="sep" aria-hidden="true">›</span>`);
    nav.dataset.trail = JSON.stringify(trail.map((c) => c.target));
  }

  function onCrumbClick(event) {
    if (event.target.closest("[data-back]")) {
      history.back();
      return;
    }
    const crumb = event.target.closest("[data-crumb]");
    if (!crumb) return;
    const targets = JSON.parse(event.currentTarget.dataset.trail);
    navigate(targets[Number(crumb.dataset.crumb)]);
  }

  // ---------------------------------------------------------------- header

  function renderStats() {
    const { files, triples, nodes, edges } = DATA.meta;
    const items = [
      [files, "Turtle files"],
      [triples, "triples"],
      [nodes, "nodes"],
      [edges, "edges"],
    ];
    byId("stats").innerHTML = items
      .map(([n, label]) => `<span><b>${formatNumber(n)}</b> ${label}</span>`)
      .join("");
  }

  // ---------------------------------------------------------------- overview

  function renderBar({ tier, key, label, count, max }) {
    const width = ((100 * count) / max).toFixed(1);
    return `<div class="bar" data-tier="${tier}" data-${key}="${escapeHtml(label)}">
      <span class="label">${escapeHtml(label)}</span>
      <span class="n">${formatNumber(count)}</span>
      <div class="track"><div class="fill" style="width:${width}%"></div></div>
    </div>`;
  }

  function renderTierCard(tier, total) {
    const key = TIERS_BY_DOMAIN.has(tier) ? "domain" : "family";
    const keyOf = key === "domain" ? domainOf : familyOf;
    const rows = sortedEntries(
      countBy({ keyOf, filter: (id) => tierOf(id) === tier }),
    ).slice(0, OVERVIEW_BARS);
    const max = rows.length ? rows[0][1] : 1;
    const bars = rows
      .map(([label, count]) => renderBar({ tier, key, label, count, max }))
      .join("");
    return `<div class="tier-card" style="--tier-color:${tierColor(tier)}">
      <h3>${escapeHtml(tierName(tier))} <span>${formatNumber(total)}</span></h3>
      <p>${escapeHtml(TIER_HELP[tier])}</p>
      <div class="bars">${bars}</div>
      <button type="button" class="browse-all" data-tier="${tier}">Browse all ${formatNumber(total)}</button>
    </div>`;
  }

  function renderDomainTable() {
    const COLUMNS = ["concept", "property", "individual", "other"];
    const rows = new Map();
    NODES.forEach((_, nodeId) => {
      const domain = domainOf(nodeId);
      if (!domain) return;
      if (!rows.has(domain))
        rows.set(domain, { concept: 0, property: 0, individual: 0, other: 0 });
      const tier = tierOf(nodeId);
      rows.get(domain)[tier in rows.get(domain) ? tier : "other"] += 1;
    });
    const total = (row) => COLUMNS.reduce((sum, c) => sum + row[c], 0);
    const sorted = [...rows.entries()].sort(
      (a, b) => total(b[1]) - total(a[1]),
    );
    const body = sorted
      .map(
        ([domain, row]) => `<tr>
          <td><span class="clickable" data-domain="${escapeHtml(domain)}" style="color:var(--accent)">${escapeHtml(domain)}</span></td>
          ${COLUMNS.map((c) => `<td class="num">${formatNumber(row[c])}</td>`).join("")}
          <td class="num">${formatNumber(total(row))}</td>
        </tr>`,
      )
      .join("");
    return `<div class="domain-table">
      <h2>By domain</h2>
      <p class="lede">FIBO is split into domains such as Foundations (FND), Business Entities (BE) and Securities (SEC). Financial Business &amp; Commerce looks huge only because it holds the market and legal entity reference data.</p>
      <div class="overflow"><table>
        <thead><tr><th>Domain</th><th class="num">Classes</th><th class="num">Properties</th><th class="num">Individuals</th><th class="num">Other</th><th class="num">Total</th></tr></thead>
        <tbody>${body}</tbody>
      </table></div>
    </div>`;
  }

  function renderOverview() {
    const tierCounts = countBy({ keyOf: tierOf });
    const cards = TIER_ORDER.map((tier) =>
      renderTierCard(tier, tierCounts.get(tier) || 0),
    ).join("");
    const pane = byId("overview");
    pane.innerHTML = `<h2>How the ${formatNumber(NODES.length)} nodes are organised</h2>
      <p class="lede">Every subject or object in the FIBO 2026Q2 Turtle files is a node. Only about a tenth of them are concepts in the everyday sense. The rest is reference data, imported vocabulary, citations and OWL plumbing. Click any bar to browse that slice.</p>
      <div class="tier-grid">${cards}</div>
      ${renderDomainTable()}`;

    pane.addEventListener("click", (event) => {
      const bar = event.target.closest(".bar");
      if (bar) {
        browseTo({
          tier: bar.dataset.tier,
          family: bar.dataset.family,
          domain: bar.dataset.domain,
        });
        return;
      }
      const browseAll = event.target.closest(".browse-all");
      if (browseAll) {
        browseTo({ tier: browseAll.dataset.tier });
        return;
      }
      const domainLink = event.target.closest("[data-domain]");
      if (domainLink) browseTo({ domain: domainLink.dataset.domain });
    });
  }

  // ---------------------------------------------------------------- browse: filters

  function matchesFilters(nodeId, { ignore = null } = {}) {
    if (ignore !== "tier" && state.tier && tierOf(nodeId) !== state.tier)
      return false;
    if (
      ignore !== "family" &&
      state.family &&
      familyOf(nodeId) !== state.family
    )
      return false;
    if (
      ignore !== "domain" &&
      state.domain &&
      domainOf(nodeId) !== state.domain
    )
      return false;
    if (state.query && !matchesQuery(nodeId, state.query)) return false;
    return true;
  }

  function renderFacet({
    title,
    key,
    keyOf,
    order = null,
    displayName = (k) => k,
  }) {
    const counts = countBy({
      keyOf,
      filter: (id) => matchesFilters(id, { ignore: key }),
    });
    const keys = order
      ? order.filter((k) => counts.has(k))
      : sortedEntries(counts).map(([k]) => k);
    const current = state[key];
    const option = (value, label, count) => {
      const active = (current || "") === value ? "active" : "";
      const n =
        count === undefined
          ? ""
          : `<span class="n">${formatNumber(count)}</span>`;
      return `<button type="button" data-${key}="${escapeHtml(value)}" class="${active}"><span>${escapeHtml(label)}</span>${n}</button>`;
    };
    return `<div>
      <h4>${title}</h4>
      <div class="facet">
        ${option("", "All")}
        ${keys.map((k) => option(k, displayName(k), counts.get(k))).join("")}
      </div>
    </div>`;
  }

  function renderFilters() {
    const pane = byId("filters");
    pane.innerHTML =
      renderFacet({
        title: "Tier",
        key: "tier",
        keyOf: tierOf,
        order: TIER_ORDER,
        displayName: tierName,
      }) +
      renderFacet({ title: "Concept family", key: "family", keyOf: familyOf }) +
      renderFacet({ title: "Domain", key: "domain", keyOf: domainOf });
  }

  function onFilterClick(event) {
    const button = event.target.closest("button");
    if (!button) return;
    const changes = {};
    for (const key of ["tier", "family", "domain"]) {
      if (key in button.dataset) changes[key] = button.dataset[key] || null;
    }
    navigate(changes);
  }

  // One pill per active facet filter, shown inside the search box.
  const PILL_FACETS = [
    { key: "tier", title: "Tier", displayName: tierName },
    { key: "family", title: "Family", displayName: (value) => value },
    { key: "domain", title: "Domain", displayName: (value) => value },
  ];

  function renderPill({ key, title, value }) {
    return `<span class="pill">
      <span class="pill-key">${title}:</span>
      <span class="pill-value">${escapeHtml(value)}</span>
      <button type="button" data-clear="${key}" aria-label="Remove ${title.toLowerCase()} filter ${escapeHtml(value)}" title="Remove filter">×</button>
    </span>`;
  }

  function renderPills() {
    byId("pills").innerHTML = PILL_FACETS.filter(({ key }) => state[key])
      .map(({ key, title, displayName }) =>
        renderPill({ key, title, value: displayName(state[key]) }),
      )
      .join("");
  }

  function onPillClick(event) {
    const button = event.target.closest("[data-clear]");
    if (button) navigate({ [button.dataset.clear]: null });
  }

  function onSearchInput(event) {
    // Typing replaces the current entry rather than adding one per keystroke.
    navigate(
      { query: event.target.value.trim().toLowerCase() },
      { replace: true },
    );
  }

  // ---------------------------------------------------------------- browse: results

  function renderResultRow(nodeId) {
    const selected = state.selected === nodeId ? "selected" : "";
    const domain = domainOf(nodeId) ? ` · ${escapeHtml(domainOf(nodeId))}` : "";
    return `<div class="row ${selected}" data-id="${nodeId}" tabindex="0" style="--tier-color:${tierColor(tierOf(nodeId))}">
      <span class="dot"></span>
      <span>
        <div class="name">${escapeHtml(labelOf(nodeId))}</div>
        <div class="sub">${escapeHtml(familyOf(nodeId))}${domain}</div>
      </span>
      <span class="kind">${escapeHtml(kindOf(nodeId))}</span>
    </div>`;
  }

  function renderResults() {
    const results = [];
    NODES.forEach((_, nodeId) => {
      if (matchesFilters(nodeId)) results.push(nodeId);
    });
    state.results = sortByLabel(results);
    byId("count").textContent = `${formatNumber(results.length)} nodes`;

    const remaining = results.length - state.shown;
    const showMore =
      remaining > 0
        ? `<button type="button" class="show-more">Show ${formatNumber(Math.min(PAGE_STEP, remaining))} more</button>`
        : "";
    byId("list").innerHTML =
      results.slice(0, state.shown).map(renderResultRow).join("") + showMore;
  }

  function onListClick(event) {
    if (event.target.closest(".show-more")) {
      state.shown += PAGE_STEP;
      renderResults();
      return;
    }
    const row = event.target.closest(".row");
    if (row) selectNode(Number(row.dataset.id));
  }

  function onListKeydown(event) {
    if (event.key !== "Enter") return;
    const row = event.target.closest(".row");
    if (row) selectNode(Number(row.dataset.id));
  }

  // ---------------------------------------------------------------- browse: detail

  function renderTermLink(nodeId) {
    const external = tierOf(nodeId) === "external-vocab" ? " external" : "";
    return `<span class="clickable${external}" data-id="${nodeId}">${escapeHtml(labelOf(nodeId))}</span>`;
  }

  function renderSection({ title, body, count }) {
    if (!body) return "";
    const n =
      count === undefined
        ? ""
        : `<span class="n">${formatNumber(count)}</span>`;
    return `<div><h4>${title} ${n}</h4>${body}</div>`;
  }

  function renderNodeList({ title, nodeIds, limit = LIST_LIMIT }) {
    if (!nodeIds.length) return "";
    const overflow =
      nodeIds.length > limit
        ? `<span class="more">and ${formatNumber(nodeIds.length - limit)} more</span>`
        : "";
    const body = `<div class="links">${nodeIds.slice(0, limit).map(renderTermLink).join("")}${overflow}</div>`;
    return renderSection({ title, body, count: nodeIds.length });
  }

  function renderRelations({ title, relations, limit = RELATION_LIMIT }) {
    if (!relations.length) return "";
    const byPredicate = new Map();
    for (const { predicate, target } of relations) {
      if (!byPredicate.has(predicate)) byPredicate.set(predicate, []);
      byPredicate.get(predicate).push(target);
    }
    let shown = 0;
    let body = "";
    for (const [predicate, targets] of sortedEntries(
      new Map([...byPredicate].map(([p, t]) => [p, t.length])),
    )) {
      const ids = byPredicate.get(predicate);
      const part = ids.slice(0, Math.max(1, limit - shown));
      shown += part.length;
      const overflow =
        ids.length > part.length
          ? ` <span class="more">and ${formatNumber(ids.length - part.length)} more</span>`
          : "";
      body += `<span class="predicate">${escapeHtml(predicate)}</span><span>${part.map(renderTermLink).join(", ")}${overflow}</span>`;
      if (shown >= limit) {
        const rest = relations.length - shown;
        if (rest > 0)
          body += `<span class="predicate"></span><span class="more">${formatNumber(rest)} more relations not shown</span>`;
        break;
      }
    }
    return renderSection({
      title,
      body: `<div class="relations">${body}</div>`,
      count: relations.length,
    });
  }

  function renderTypes(nodeId) {
    const tier = tierOf(nodeId);
    if (tier === "concept" || tier === "property") return "";
    const names = typeNamesOf(nodeId);
    if (!names.length) return "";
    const links = names
      .map((typeName) => {
        const classId = INDEX.classByName.get(typeName);
        return classId === undefined
          ? `<span class="external">${escapeHtml(typeName)}</span>`
          : renderTermLink(classId);
      })
      .join("");
    return renderSection({
      title: "Type",
      body: `<div class="links">${links}</div>`,
    });
  }

  // Where a term's link should go, and what the tooltip should say.
  // - OMG publishes each Commons and LCC ontology as one page at its namespace
  //   URL and returns 404 for individual term IRIs, so those go to the namespace.
  // - Everything else links to the term IRI itself.
  const OMG_PREFIX = "https://www.omg.org/spec/";
  function linkFor(nodeId) {
    const iri = iriOf(nodeId);
    const ns = POOL.ns[field(nodeId, "ns")];
    if (iri.startsWith(OMG_PREFIX) && ns) {
      return {
        href: ns,
        title: `${iri}\nOMG serves one page per ontology; this opens the ${ns} page.`,
      };
    }
    return { href: iri, title: iri };
  }

  // The shortcode under the title (the CURIE, or the local name when the
  // namespace has no prefix), linking to where the term is documented;
  // hovering shows the full IRI.
  function renderNameLink(nodeId) {
    const name = nameOf(nodeId);
    if (!name) return "";
    const { href, title } = linkFor(nodeId);
    const shortcode = curieOf(nodeId) || name;
    return `<div class="mono"><a href="${escapeHtml(href)}" title="${escapeHtml(title)}" target="_blank" rel="noopener">${escapeHtml(shortcode)}</a></div>`;
  }

  function renderDetail(nodeId) {
    const tier = tierOf(nodeId);
    const constraints = constraintsOf(nodeId);
    const badges = [
      `<span class="badge tier" style="--tier-color:${tierColor(tier)}">${escapeHtml(tierName(tier))}</span>`,
      `<span class="badge">${escapeHtml(kindOf(nodeId))}</span>`,
      domainOf(nodeId)
        ? `<span class="badge">${escapeHtml(domainOf(nodeId))}</span>`
        : "",
      `<span class="badge">${escapeHtml(familyOf(nodeId))}</span>`,
    ].join("");

    return `<div>
        <h2>${escapeHtml(labelOf(nodeId))}</h2>
        ${renderNameLink(nodeId)}
      </div>
      <div class="badges">${badges}</div>
      ${definitionOf(nodeId) ? `<div class="definition">${escapeHtml(definitionOf(nodeId))}</div>` : ""}
      ${renderTypes(nodeId)}
      ${renderNodeList({ title: "Superclasses", nodeIds: superclassesOf(nodeId) })}
      ${renderNodeList({ title: "Subclasses", nodeIds: sortByLabel([...INDEX.subclasses[nodeId]]) })}
      ${renderSection({
        title: "Constraints",
        count: constraints.length || undefined,
        body: constraints
          .map((c) => `<div class="constraint">${escapeHtml(c)}</div>`)
          .join(""),
      })}
      ${renderNodeList({ title: "Instances", nodeIds: sortByLabel([...(INDEX.instancesOf.get(nodeId) || [])]) })}
      ${renderRelations({ title: "Relations from this node", relations: INDEX.outgoing[nodeId] })}
      ${renderRelations({ title: "Referenced by", relations: INDEX.incoming[nodeId] })}
      ${renderSection({ title: "Graph degree", body: `<div class="mono">in ${field(nodeId, "in")} · out ${field(nodeId, "out")}</div>` })}
      ${renderSection({ title: "Defined in", body: fileOf(nodeId) ? `<div class="mono">${escapeHtml(fileOf(nodeId))}</div>` : "" })}`;
  }

  function renderDetailPane() {
    const pane = byId("detail");
    const nodeId = state.selected;
    if (nodeId === null) {
      pane.innerHTML = `<div class="empty">Select a node to see its details.</div>`;
      pane.dataset.nodeId = "";
      return;
    }
    if (pane.dataset.nodeId === String(nodeId)) return;
    pane.dataset.nodeId = String(nodeId);
    pane.innerHTML = renderDetail(nodeId);
    pane.scrollTop = 0;
  }

  function onDetailClick(event) {
    const term = event.target.closest("[data-id]");
    if (term) selectNode(Number(term.dataset.id));
  }

  // ---------------------------------------------------------------- hierarchy

  function renderTreeNode(nodeId) {
    const external = tierOf(nodeId) !== "concept";
    const count = descendantCount(nodeId);
    const family =
      external && familyOf(nodeId) === "Other concepts" ? "" : familyOf(nodeId);
    return `<div class="tree-node ${external ? "external" : ""}" data-id="${nodeId}">
      <div class="tree-head">
        <span class="toggle">${INDEX.subclasses[nodeId].length ? "+" : ""}</span>
        <span class="label">${escapeHtml(labelOf(nodeId))}</span>
        ${count ? `<span class="n">${formatNumber(count)}</span>` : ""}
        <span class="family">${escapeHtml(family)}</span>
      </div>
      <div class="children" hidden></div>
    </div>`;
  }

  function hierarchyRoots() {
    const roots = new Set();
    NODES.forEach((_, nodeId) => {
      if (tierOf(nodeId) !== "concept" || kindOf(nodeId) !== "Class") return;
      const supers = superclassesOf(nodeId);
      if (!supers.length) roots.add(nodeId);
      for (const superId of supers)
        if (tierOf(superId) !== "concept") roots.add(superId);
    });
    return sortByLabel([...roots]).sort(
      (a, b) => descendantCount(b) - descendantCount(a),
    );
  }

  function renderHierarchy() {
    const pane = byId("hierarchy");
    if (pane.dataset.rendered) return;
    pane.dataset.rendered = "1";
    pane.innerHTML = `<h2>Class hierarchy</h2>
      <p class="lede">Every FIBO class, arranged under its superclasses. Italic roots are terms from imported ontologies (OMG Commons and others) that FIBO builds on but does not define here. Counts are descendants. Click a name to open it in the browser.</p>
      <div class="tree">${hierarchyRoots().map(renderTreeNode).join("")}</div>`;
  }

  function onHierarchyClick(event) {
    const head = event.target.closest(".tree-head");
    if (!head) return;
    const node = head.parentElement;
    const nodeId = Number(node.dataset.id);
    if (event.target.classList.contains("label")) {
      browseTo({ tier: "concept", selected: nodeId });
      return;
    }
    const children = node.querySelector(".children");
    if (!children.dataset.rendered) {
      children.dataset.rendered = "1";
      children.innerHTML = sortByLabel([...INDEX.subclasses[nodeId]])
        .map(renderTreeNode)
        .join("");
    }
    children.hidden = !children.hidden;
    head.querySelector(".toggle").textContent = children.hidden ? "+" : "−";
  }

  // ---------------------------------------------------------------- boot

  function bindEvents() {
    for (const button of document.querySelectorAll(".views button")) {
      button.addEventListener("click", () =>
        navigate({ view: button.dataset.view, selected: null }),
      );
    }
    byId("crumbs").addEventListener("click", onCrumbClick);
    byId("pills").addEventListener("click", onPillClick);
    window.addEventListener("popstate", onPopState);
    byId("filters").addEventListener("click", onFilterClick);
    byId("search").addEventListener("input", onSearchInput);
    for (const button of document.querySelectorAll(".scope button")) {
      button.addEventListener("click", () =>
        setSearchScope(button.dataset.scope),
      );
    }
    byId("list").addEventListener("click", onListClick);
    byId("list").addEventListener("keydown", onListKeydown);
    byId("detail").addEventListener("click", onDetailClick);
    byId("hierarchy").addEventListener("click", onHierarchyClick);
  }

  function boot() {
    renderStats();
    renderOverview();
    bindEvents();
    loadSearchScope();
    renderSearchScope();
    applyState(parseHash(location.hash));
    render();
    history.replaceState(
      { depth: history.state?.depth ?? 0 },
      "",
      `${location.pathname}${location.search}${serializeState()}`,
    );
  }

  boot();
})();
